    (3, "[9H51DT03] Kỹ năng: Chứng minh bốn đỉnh của hình chữ nhật đồng viên và xác định các yếu tố đối xứng"),
    (4, "[9H51DT04] Kỹ năng: Chứng minh bốn điểm đồng viên từ hai tam giác vuông chung cạnh huyền và tính chất đường trung trực"),
