dang_p2_b5_c3_hh8 = [
    (1, "[8H35BT01] Kỹ năng: Phân tích tính chất diện tích, chu vi và hai đường chéo của hình thoi"),
    (2, "[8H35BT02] Kỹ năng: Phân tích tính chất góc, đường chéo và diện tích của hình vuông"),
    (3, "[8H35BT03] Kỹ năng: Khai thác mối quan hệ giữa hình bình hành, hình thoi và hình vuông qua hai đường chéo"),
    (4, "[8H35BT04] Kỹ năng: Nhận diện và tính toán góc, đường chéo của hình thoi tạo bởi hai tam giác đều chung cạnh"),
    (5, "[8H35BT05] Kỹ năng: Chứng minh và tính diện tích hình vuông tạo bởi giao điểm hai đường tròn bằng nhau"),
    (6, "[8H35BT06] Kỹ năng: Vận dụng tính chất đường trung bình của tam giác vuông cân để chứng minh và tính chu vi hình vuông"),
    (7, "[8H35BT07] Kỹ năng: Xác định tính chất tứ giác tạo bởi trung điểm bốn cạnh của tứ giác có hai đường chéo vuông góc"),
    (8, "[8H35BT08] Kỹ năng: Khai thác tính chất hình thoi, hình vuông tạo bởi trung điểm bốn cạnh của hình thang cân"),
    (9, "[8H35BT09] Kỹ năng: Tính độ dài các cạnh hình chữ nhật khi biết chu vi và điều kiện vuông góc tại trung điểm cạnh"),
    (10, "[8H35BT10] Kỹ năng: Vận dụng tính chất hình bình hành, hình thoi và tính cứng vững của tam giác vào bài toán khung gỗ bị xô lệch"),
    (11, "[8H35BV11] Kỹ năng: Tìm điều kiện của tam giác để tứ giác dựng từ trung điểm hai cạnh trở thành hình thoi hoặc hình vuông"),
    (12, "[8H35BV12] Kỹ năng: Phân tích tứ giác tạo bởi giao điểm bốn đường phân giác trong của hình bình hành, hình chữ nhật và hình thoi"),
    (13, "[8H35BV13] Kỹ năng: Dựng hình bình hành phụ trên tia kéo dài và biện luận tính chất góc, hình dạng tứ giác"),
    (14, "[8H35BV14] Kỹ năng: Giải bài toán tổng hợp liên hoàn từ hình chữ nhật đến hình thoi và hình vuông trên tam giác vuông"),
    (15, "[8H35BV15] Kỹ năng: Dựng tam giác bằng nhau để chứng minh hệ thức cộng đoạn thẳng và tính chu vi tam giác trong hình vuông"),
    (16, "[8H35BV16] Kỹ năng: Vận dụng tính chất hình chữ nhật và tam giác bằng nhau để chứng minh tính bất biến của hiệu khoảng cách trên tam giác cân"),
    (17, "[8H35BV17] Kỹ năng: Chứng minh hình vuông nội tiếp và tính diện tích tứ giác tạo bởi các đoạn bằng nhau trên bốn cạnh hình vuông"),
    (18, "[8H35BV18] Kỹ năng: Vận dụng tính chất hình vuông và tam giác bằng nhau để chứng minh hai đường thẳng vuông góc và tính độ dài đoạn thẳng"),
    (19, "[8H35BV19] Kỹ năng: Khai thác tính chất đường chéo, góc vuông và tính bất biến khoảng cách của hai hình vuông chung đỉnh"),
    (20, "[8H35BV20] Kỹ năng: Dựng hai hình vuông phía ngoài tam giác để chứng minh hai đường thẳng vuông góc và hệ thức độ dài đoạn thẳng"),
]